D.ItemDescriptions[19245]={["659a2832a7d8d78d:40"]="休息是好的，但疲倦是他的兄弟。"}
D.ItemDescriptions[19246]={["5653f580863c58af:51"]="简单就是美。"}
D.ItemDescriptions[19247]={["2f3cd9049d57082d:31"]="不要让战争的潮水将你淹没。"}
D.ItemDescriptions[19248]={["5b25b2744f8ec68b:34"]="你让你的敌人永远闭嘴。"}
D.ItemDescriptions[19249]={["44770feadfbf1a5d:36"]="伪善在你面前原形毕露。"}
D.ItemDescriptions[19250]={["5833aea7e6a1dc8c:32"]="教给别人越多，自己学得越多。"}
D.ItemDescriptions[19251]={["c1a4d59f1579a866:56"]="考验你的时刻即将到来。"}
D.ItemDescriptions[19252]={["39980a068c8703db:32"]="接受你听到的下一个建议。"}
D.ItemDescriptions[19253]={["6edaffd4624fd427:31"]="不要随便踢侏儒。"}
D.ItemDescriptions[19254]={["2dfd96b4c59b0c29:49"]="神圣之盾和炉石并不是英雄所必备的。"}
