D.ItemDescriptions[19378]={["0e601a2f8c71f3a2:70"]="你从未见过这样的丝线，它仿佛是由金属制成的。"}
D.ItemDescriptions[19379]={["12b3e28fa2f3a580:101"]="银色的液体在乌黑的外壳中涌动，这件物品非常纯净，它散发着强大的能量。"}
