D.ItemDescriptions[19389]={["8329cfd2e5c327c9:97"]="这套护肩似乎是由多种龙类的皮缝合在一起而制成的。它散发着腐烂的气息。"}
D.ItemDescriptions[19390]={["95db0646c1334f27:124"]="当你把手放在这双手套上时，你感觉到了一丝寒意。它们似乎是用幼龙的皮制成的——许多幼龙的皮。"}
D.ItemDescriptions[19396]={["d65f5c9288adeb77:68"]="这根腰带似乎是由多种龙类的皮缝合在一起而制成的。"}
