D.ItemDescriptions[23167]={["c3ff47e91dc50052:33"]="蛇形的饰纹非常生动。"}
D.ItemDescriptions[23193]={["8a5852bd49e2e988:65"]="教你学会召唤纳克萨玛斯死亡战马。这是一种速度非常快的坐骑。"}
D.ItemDescriptions[23205]={["15c37f8cbccd9665:46"]="在地狱火半岛生长的一种植物的叶子。"}
D.ItemDescriptions[23211]={["55687ba2c4878bcd:17"]="软软的，甜甜的……"}
D.ItemDescriptions[23214]={["5ec894169e1d1903:43"]="制造投石车燃烧弹的关键材料。"}
D.ItemDescriptions[23215]={["9a2c78642d3a8acf:43"]="甜美的饼干、巧克力和蜜饯！"}
D.ItemDescriptions[23217]={["8d3d017b1cad3fe2:59"]="它不停地摇摆，仿佛里面的幼崽随时会破壳而出。"}
D.ItemDescriptions[23218]={["8a9b98d9de37be28:106"]="虚空行者的精华散发出强大的能量。这正是斯克里想要用来“改良”他的飞艇引擎的材料。"}
D.ItemDescriptions[23222]={["4e4c6154354ca261:54"]="又厚又重的变异裂蹄牛的毛皮，不过有些褪色。"}
D.ItemDescriptions[23223]={["ec2de21955ea9346:51"]="一堆扭曲的骨头，来自于某只曾经强大无比的动物。"}
D.ItemDescriptions[23227]={["ac20cb135c021f26:49"]="交给可口可乐兑奖使者即可换取夏日礼包"}
D.ItemDescriptions[23231]={["fb310d82b23b3017:57"]="一头变异的外域野兽的肌腱，苍老而扭曲。"}
D.ItemDescriptions[23239]={["f41707d46b015403:58"]="只有最强壮的秃鹫才有这么完美的翅膀。"}
D.ItemDescriptions[23248]={["1db3be3db88c643c:56"]="鲜嫩多汁的地狱野猪肉，但不是很有韧性。"}
D.ItemDescriptions[23270]={["50fbd24809a9f18f:48"]="惨白而恶臭的肉块，取自一头被污染的地狱野猪。"}
D.ItemDescriptions[23320]={["dc732785c6c5b11c:57"]=S[17106]}
D.ItemDescriptions[23338]={["1a62515fb2bc4752:65"]="这只箱子似乎在某条大虫子的消化系统中待过很长时间。"}
D.ItemDescriptions[23343]={["41cfdfb763f05a66:77"]="虽然这只背包已经破旧不堪，但它的精美做工仍表明它是出自血精灵工匠之手。"}
D.ItemDescriptions[23352]={["e870ad20353b5c25:56"]="一股异常强大的虚空行者能量。"}
D.ItemDescriptions[23355]={["32fc7f4dab327dfe:21"]="请勿食用。"}
D.ItemDescriptions[23387]={["0f8d3d4b1c64c9c0:44"]="用来装饰或者挠脚心的完美材料。"}
D.ItemDescriptions[23417]={["bd30844f835727c2:45"]="被储存在水晶中的法术令这块水晶散发出微微的光芒。"}
