D.ItemDescriptions[23658]={["71398089dcc5473e:89"]="一个色调明亮的丝绸包。似乎它被黑铁矮人的宠物撕咬了许久。"}
D.ItemDescriptions[23660]={["9627a2f42280aa59:65"]="一把做工细致的精灵剑，上面沾满了黑铁矮人的矿渣。"}
D.ItemDescriptions[23661]={["72bed8ec02f85dd7:58"]="乌瑟尔·光明使者在战死之前携带的神圣印记。"}
D.ItemDescriptions[23670]={["19c77a9dbd49fb22:39"]="一瓶从萨兰纳尔的月亮井中采集的水。"}
D.ItemDescriptions[23671]={["50aa4d27aa879cb4:43"]="这块水晶散发着大地元素的能量。"}
D.ItemDescriptions[23675]={["44e902a060f6230f:46"]="控制你的超级机器助手3000型！"}
D.ItemDescriptions[23676]={["a5cee494029b2a27:32"]="鲜嫩的肉汁令你垂涎欲滴。"}
D.ItemDescriptions[23677]={["b1a3db744e494619:15"]="结实耐用。"}
D.ItemDescriptions[23678]={["925136b09a974c07:57"]="从一头夜行豹幼崽的胃中掏出的水晶，看起来很眼熟。"}
D.ItemDescriptions[23679]={["cc6f4c7d8d378ba2:58"]="一根看起来很少见的图腾，上面刻着古老的符文。"}
D.ItemDescriptions[23681]={["2c59861878ce64a1:58"]="这枚精华中散发出强大而狂暴的元素能量。"}
D.ItemDescriptions[23687]={["f82116e87bce61ab:45"]="爪子已经严重磨损了，但依然如剃刀般锋利。"}
D.ItemDescriptions[23688]={["b73cef19b2095910:48"]="灰烬中散发的热量几乎让你无法忍受。"}
D.ItemDescriptions[23691]={["113060f20ccf7e19:51"]="邪恶的魔法能量使你几乎无法拿着它。"}
D.ItemDescriptions[23694]={["c0e94063a0b20272:52"]="从枯木巨魔手中夺回来的狮鹫卵，尚未孵化。"}
D.ItemDescriptions[23695]={["2989970c6a6c3531:78"]="一张沙德拉洛的手绘地图，标记了被偷走的狮鹫卵的位置。"}
