D.ItemDescriptions[23723]={["3757211d83e5c43c:43"]="卡加斯·刃拳酋长的令人生畏的武器。"}
D.ItemDescriptions[23726]={["bf5a530d4ae7383e:94"]="仍在冒烟的灰烬中透出暗淡的紫色光芒，但是并不灼热。它的冰冷掩盖了蕴涵在灰烬中的巨大能量。"}
D.ItemDescriptions[23733]={["ddd0c1ec650ab37d:40"]="火炬散发出的热量让你几乎无法忍受。"}
