D.ItemDescriptions[27940]={["2173cc7ac1f0d107:122"]="将你的灵魂绑定在这个世界中，当你死亡之后，灵魂还可以跑回尸体身边复活，避免万劫不复的命运！"}
D.ItemDescriptions[27941]={["d753d5bae8da96b9:98"]="这件护符可以让危险的小动物不再有害。但是如果你伤害了小动物，它强大的魔法屏障会暂时失效。"}
D.ItemDescriptions[27944]={["cc993a17e93338b4:66"]="戴上之后，你就可以在怪物的尸体上找到值钱的宝贝！"}
