D.ItemDescriptions[27976]={["b2688406962ae003:107"]="这件坠饰可以集中生命的力量，让你从普通的食物和饮料中抽取强大的力量，甚至可以帮你迅速从重伤中康复！"}
D.ItemDescriptions[27978]={["1e1d89febb0e11d5:72"]="冒险并不是脏乱的理由。现在你可以随身携带肥皂，走到哪里洗到哪里啦！"}
