D.ItemDescriptions[33013]={["bf6a0e390b1b4d9e:27"]="这张地图充其量也只能说是草图……"}
D.ItemDescriptions[33014]={["619bcafa36f46c43:42"]="由大自然的鬼斧神工历经百年制成！"}
D.ItemDescriptions[33015]={["c9b3bf8b6bd1ccb2:69"]="这些传单上的文字被修改过，意在羞辱塞拉摩叛逃者。"}
