D.ItemDescriptions[33821]={["5981b3e35aa96c14:46"]="三颗心中的一颗，看起来有点像洋葱。"}
D.ItemDescriptions[33826]={["8eb8ca68a99b28a7:17"]="它散发出生命的脉动。"}
D.ItemDescriptions[33827]={["6a9cee2878de9e39:79"]="这篇洋洋洒洒数千页长的文章经过防水处理，上面写满了纳迦的文字。"}
D.ItemDescriptions[33833]={["d473a6cc5c165f47:34"]="被它抽一下想必很疼。"}
