D.ItemDescriptions[33835]={["6d3d623c5516f66b:82"]="这是节点亲王沙法尔的魔法能量来源。真可惜，你根本不知道该如何使用它。"}
D.ItemDescriptions[33836]={["729335b10329005a:104"]="很难相信这颗宝石中居然装着许多牺牲者的灵魂。不过，你的确可以感觉到从里面传来的躁动。"}
D.ItemDescriptions[33839]={["4d86d5a5b70d5852:59"]="终于可以复仇了！美味多汁的卡利鸟肉，啃起来果然是大快人心。"}
D.ItemDescriptions[33840]={["291c50f0348d238d:69"]="教授说得对，摩摩尔的“低语”真的有物质形态！"}
