D.ItemDescriptions[36780]={["b0cf89c50ff00838:35"]="这封信写得非常潦草，难以辨认。"}
D.ItemDescriptions[36805]={["1ad7bec0cb59f963:7"]="有些松散"}
D.ItemDescriptions[36806]={["3c84bf51aea0aa28:23"]="如果你有一把雨伞就好了。"}
