D.ItemDescriptions[43511]={["793bd20b5c06708c:52"]="你无法想象还有什么能比这东西更恶心。"}
D.ItemDescriptions[43512]={["ddb0b688844e6283:49"]="这只蘑菇发出的恶臭让你呕吐不止。"}
D.ItemDescriptions[43516]={["69f5e24752b91ada:50"]=S[13076]}
D.ItemDescriptions[43521]={["b8fd89c76de529e0:23"]="稍微有点大……"}
D.ItemDescriptions[43534]={["0d3372325b6c3a2d:103"]=S[18706]}
D.ItemDescriptions[43539]={["0d3372325b6c3a2d:103"]=S[18706]}
D.ItemDescriptions[43541]={["0d3372325b6c3a2d:103"]=S[18706]}
D.ItemDescriptions[43542]={["0d3372325b6c3a2d:103"]=S[18706]}
D.ItemDescriptions[43544]={["0d3372325b6c3a2d:103"]=S[18706]}
D.ItemDescriptions[43550]={["0d3372325b6c3a2d:103"]=S[18706]}
D.ItemDescriptions[43555]={["9b1ab96642c1e235:29"]="巡逻队的重要成员！"}
D.ItemDescriptions[43569]={["a366cec57c1d6fbc:20"]="饮之不尽。"}
D.ItemDescriptions[43570]={["a366cec57c1d6fbc:20"]="饮之不尽。"}
D.ItemDescriptions[43573]={["dff945cdcf52074a:29"]="它们闪着悲伤与哀痛的光芒。"}
D.ItemDescriptions[43577]={["9c24340ba08d1138:31"]="甲壳和螯足光亮如新！"}
D.ItemDescriptions[43589]={["c9b9ace17f014944:40"]="为表彰在冬拥湖作战而颁发的奖章"}
D.ItemDescriptions[43597]={["422c727d5042b2d6:43"]="教你学会制作泰坦神铁霜卫指环。"}
D.ItemDescriptions[43599]={["24146c488b5a7fa3:31"]=S[13072]}
D.ItemDescriptions[43609]={["6fa1ef3693e5da97:31"]="死去士兵的骨骸。"}
D.ItemDescriptions[43610]={["5e4c087546d54a4c:24"]="一顶破旧的联盟头盔。"}
D.ItemDescriptions[43616]={["c0354c804ec85677:28"]="一件被刺穿的联盟胸甲。"}
D.ItemDescriptions[43627]={["b591ed2d622c57b6:30"]="格罗姆，我的老朋友，愿你安息。"}
D.ItemDescriptions[43628]={["c6d2d66ebc5c70ad:33"]="阿尔萨斯，我的挚爱，请回到我身边来。"}
D.ItemDescriptions[43629]={["987d2c1916d04cf6:105"]="年轻的阿尔萨斯必须学会以耐心控制自己的力量。我祈祷他能了解到领袖的真谛在于品德，而非蛮力。"}
D.ItemDescriptions[43630]={["9e1bd120745d95d5:74"]="我希望泰兰能够茁壮成长，保卫他所关心的人。"}
D.ItemDescriptions[43631]={["73035a050d0b0512:64"]="许愿是蠢货的消遣。这枚金币就当是挖掉你眼睛的报酬吧。"}
D.ItemDescriptions[43632]={["36dae030d8af4bfd:76"]="希望姐妹们和我一起长大，一起出嫁。这枚金币似乎很古老了。"}
D.ItemDescriptions[43633]={["5600e716ddcf51d3:88"]="那个名叫吉安娜的年轻学徒，就一名人类女子来说，已经算是很有吸引力了。我希望她能认识到我的优雅和强大。"}
D.ItemDescriptions[43634]={["a60abdfbb1ffbeda:79"]="听着，小小的许愿泉。把你全部的力量都交给我，不然有你好看。"}
D.ItemDescriptions[43635]={["0d12aad6a6e14393:64"]="有时候……我真希望有人能给我一个热情而温暖的拥抱。"}
D.ItemDescriptions[43636]={["ad66c9e8b22d0775:81"]="真希望跟我打招呼的那些家伙不再讲有关侏儒或者时间旅行的冷笑话。"}
D.ItemDescriptions[43637]={["2677d7a13888837a:24"]="布莱恩·铜须到此一游。"}
D.ItemDescriptions[43638]={["052615d7ea25b854:79"]="我希望有一天可以退休回到自己的小别墅中颐养天年，养几只小狗当宠物。"}
D.ItemDescriptions[43639]={["d719814348a9f884:81"]="我已经是一个王国的储君了，将要治理大片的疆土。还能许什么愿呢？不如来一个凉快点的座位……"}
D.ItemDescriptions[43640]={["b3395ee66277002f:48"]="我想知道你要如何在我的怒火中幸存下来，小喷泉。"}
D.ItemDescriptions[43641]={["ab9304bdb728ed12:48"]="我希望自己能快快长大。好像我一直都是10岁的样子。"}
D.ItemDescriptions[43643]={["18ad47c0c4b3352b:61"]="我希望父亲和兄弟们比我更健康长寿。我自己当不当国王无所谓。"}
D.ItemDescriptions[43644]={["859ee33cd3881ad3:76"]="我真健忘！真希望自己的记忆力更好一点。等等，我是不是已经扔了一枚硬币进去？"}
D.ItemDescriptions[43645]={["974262c7cf180a88:63"]="好像有人想在喷泉里钓鱼。谁会傻到这种地步？"}
D.ItemDescriptions[43653]={["2e0fd5da64ba6e45:37"]="鱼身上可以看到细小的牙印。"}
D.ItemDescriptions[43658]={["2422520448d0287d:32"]="这把锉刀上有一点绿色的锈斑。"}
D.ItemDescriptions[43659]={["9eb98b29cdb6b802:58"]="这把小刀的状态表明，今年的相关业务利润极高。"}
D.ItemDescriptions[43662]={["b153cc522b2afc85:122"]="你还以为这把斧头应该非常锋利，但它并不锋利。维库人必定是凭借自己的蛮力去强行劈砍对手。"}
D.ItemDescriptions[43665]={["0de4226f33c63b10:76"]="悲伤的故事，悲剧的结果。如果玛里苟斯对克莉斯塔萨进行的百般折磨没有将她逼疯该有多好。"}
D.ItemDescriptions[43668]={["e86a2655fb20e822:107"]="你不是很确定这东西究竟是用什么制成的。它无疑散发出强大的奥术能量，但是这样一件小东西又怎么会如此重要呢？"}
D.ItemDescriptions[43669]={["622b5b6ddee51b26:57"]="伊米隆国王留下的唯一一件用以纪念他的爱人——安格博达女王的信物。"}
D.ItemDescriptions[43670]={["b93c1fd3432c8daa:54"]="在这件物品的持有者死后，物品中的魔精似乎全部消失了。"}
D.ItemDescriptions[43671]={["0d3372325b6c3a2d:103"]=S[18706]}
D.ItemDescriptions[43672]={["0d3372325b6c3a2d:103"]=S[18706]}
D.ItemDescriptions[43673]={["0d3372325b6c3a2d:103"]=S[18706]}
D.ItemDescriptions[43674]={["0d3372325b6c3a2d:103"]=S[18706]}
D.ItemDescriptions[43675]={["1ddb9ef2fdc89c11:59"]="流沙之战……如果能彻底忘掉它就好了。"}
D.ItemDescriptions[43676]={["1dbec1226f16e273:80"]="啊，你为什么不在乎我？阿比迪斯，我愿意跟随你到天涯海角。希望你能在乎我一点……"}
D.ItemDescriptions[43677]={["fdc687bf8c70b8d6:51"]="这喷泉的工作原理是什么？我想自己也造一座出来。"}
D.ItemDescriptions[43678]={["1304b6afc84bc882:116"]="给我力量接受那些我无法改变的事情，给我勇气改变那些我可以改变的事情，给我智慧看清这两者之间的差别。"}
D.ItemDescriptions[43679]={["f7150c670e896d28:56"]="愿圣光保佑我们这支诺森德远征队。"}
D.ItemDescriptions[43680]={["8e30fcf628b5643f:76"]="希望家乡的那场暴动马上平息。我不想看到任何人受伤害。"}
D.ItemDescriptions[43681]={["f50b93aef98f5353:52"]="希望我的儿子阿尔萨斯能为他的子民鞠躬尽瘁。"}
D.ItemDescriptions[43682]={["38b3cae5db668eac:57"]="希望小凯尔萨斯能明白，总有一天，他要肩负起领导所有子民的重任。"}
D.ItemDescriptions[43683]={["18930f123a0bee29:47"]="图拉扬和奥蕾莉亚，无论你们在哪里，希望你们安然无恙。"}
D.ItemDescriptions[43684]={["ba182758f28caccd:83"]="<你感觉到脑袋里有三个声音在说话，其中两个声音很嘈杂，第三个隐约可以分辨出内容。>"}
D.ItemDescriptions[43685]={["a188fb36bbd15b81:15"]="伊利丹去哪了？"}
D.ItemDescriptions[43686]={["1eb4f42815823fa1:81"]="希望我的妹妹们可以了解自己的潜能，以她们的事迹为风行者家族争光。"}
D.ItemDescriptions[43687]={["44e209dc6ded0f91:65"]="我真的希望你们这些法师少啃几本书，多用用脑子。"}
D.ItemDescriptions[43693]={["8fb8b02e48d7e045:60"]="真是难以想象，强大的犀牛之神只留下了这么一点残迹。"}
D.ItemDescriptions[43694]={["eeef29c9900d003e:56"]="看起来，这次掉进锅里之后没有发生什么奇遇。"}
D.ItemDescriptions[43695]={["4c43794010c7193d:27"]="也可以用来除掉油渍。"}
D.ItemDescriptions[43696]={["4c43794010c7193d:27"]="也可以用来除掉油渍。"}
D.ItemDescriptions[43697]={["7a54c60b9d891df4:79"]="真是奇怪的装置。你从没有见过如此诡异特别的东西。"}
D.ItemDescriptions[43698]={["9d6d0e19bc8fb050:35"]=S[13079]}
D.ItemDescriptions[43699]={["2ab10532e8a8b225:52"]="这东西上面记载着信息？真的？明明一个字都没有啊！"}
D.ItemDescriptions[43701]={["0e686b8c0135a0b1:75"]="真希望我跟那个整天扛着木材闲逛的表哥换一下……"}
D.ItemDescriptions[43702]={["11431ec8a45ecf59:92"]="我希望能向芸芸众生宣讲圣光之道，教他们学会理解三大美德的价值。"}
D.ItemDescriptions[43703]={["97933fb5cf6622b2:71"]="我希望女儿天天快乐，并且可以接受我。她在这里感觉很拘束……"}
D.ItemDescriptions[43704]={["54e5a7b1966d85fe:50"]="我能许愿一个更加舒适的马鞍吗？我的屁股很疼。"}
D.ItemDescriptions[43705]={["9d8999231d499f0e:28"]="我希望有一个巨魔死掉……现在就死。"}
D.ItemDescriptions[43706]={["19f3f1de94cc77b5:58"]="我希望阿尔萨斯那个坏蛋掉进一堆猛犸人的便便里！"}
D.ItemDescriptions[43707]={["704d6f0acdeffb71:74"]="希望提里奥的诺森德之旅以胜利告终，或者，希望他光荣地战死在沙场上。"}
D.ItemDescriptions[43708]={["def533b0d51b8a39:67"]="盗贼这个行业可真不轻松。我希望能为了真正的理想而奋斗……"}
D.ItemDescriptions[43709]={["b83609c97b7e99a6:35"]="希望我的故事也能被写进书中。"}
D.ItemDescriptions[43710]={["ba7790562af23a4f:67"]="哈！吉尔尼斯的喷泉可以实现的愿望比达拉然的喷泉多十倍！"}
D.ItemDescriptions[43711]={["a81eacbae759e9cd:24"]="希望父亲能回到我身边……"}
D.ItemDescriptions[43712]={["c7fabe21ed670b58:86"]="我为了那些仍在格瑞姆巴托受苦的兄弟姐妹而祈祷。我一定要解救他们。一定。"}
D.ItemDescriptions[43713]={["ac46c06ba01afc32:77"]="爆炸。现在就爆炸。我希望能看到爆炸。快爆炸！这硬币肯定是有问题，不知道它到底能不能爆炸。"}
D.ItemDescriptions[43714]={["cec2a5757377cf82:23"]="希望我能拿回这枚铜币……"}
D.ItemDescriptions[43715]={["e2fc2f4373c1f9ec:60"]="只要一次就行了——真的，一次就行——让那个姑娘和我一起骑狮鹫去兜风。"}
D.ItemDescriptions[43716]={["9c05057c7e5eaa21:53"]="希望诺森德的水变暖和一点，冻得我都快睡着啦！"}
D.ItemDescriptions[43717]={["f4a1229a57fea195:59"]="我希望那个英俊的贵族，普瑞斯托大人，能够注意到我！他真是太帅了！"}
D.ItemDescriptions[43718]={["fb172051601eb042:42"]="我希望能长出漂亮而浓密的胡须。"}
D.ItemDescriptions[43719]={["4b6b8481d992b00a:50"]="总有一天，我要比这些法师都更厉害！"}
D.ItemDescriptions[43720]={["312f3362c60b148b:98"]="我希望能调离暴风城，并且再次见到瑟尔希。这座城市一点都不好。"}
D.ItemDescriptions[43721]={["2c26e3da0a9d5453:121"]="你们这些法师居然拒绝帮助两个相爱的人走到一起，只因为其中一个还没有发现他们是天造地设的一对？我希望你们全部完蛋。"}
D.ItemDescriptions[43722]={["96ec64f45edd93a5:61"]="(薩拉斯語) Asto're da shan're. Turus Fulo Il'amare, A'Talah Adore. Isera'duna..."}
D.ItemDescriptions[43723]={["8adb93c32470b882:52"]="希望杉德尔船长快点把我的酒运过来。"}
D.ItemDescriptions[43724]={["fa2067743383c8f9:45"]="戒指？这东西更像是一条项链，而且还是很重的那种！"}
D.ItemDescriptions[43726]={["a81c009fd2f3cf3a:95"]="这位地穴领主仍然戴着他的王冠，虽然他很早以前投靠巫妖王的时候就已经失去了王位。"}
D.ItemDescriptions[43821]={["ab2f56f3c15f44a6:22"]="呃……它还在跳动！"}
D.ItemDescriptions[43823]={["a27f7295de401c98:39"]="当作战利品挂在墙上一定不错。"}
D.ItemDescriptions[43824]={["4b52f135ef522cc8:34"]="记载着高阶魔法知识的秘密。"}
D.ItemDescriptions[43825]={["0d3372325b6c3a2d:103"]=S[18706]}
D.ItemDescriptions[43827]={["0d3372325b6c3a2d:103"]=S[18706]}
D.ItemDescriptions[43843]={["d5ec913e3c2c6d2d:19"]="能用就行。"}
D.ItemDescriptions[43850]={["6dc0f0b4df0d38f5:66"]="此证书对小伙伴、恶魔和队友无效。"}
D.ItemDescriptions[43867]={["0d3372325b6c3a2d:103"]=S[18706]}
D.ItemDescriptions[43868]={["0d3372325b6c3a2d:103"]=S[18706]}
D.ItemDescriptions[43876]={["19ecd5d35ff3e7e8:63"]="使裁缝有更高的几率在诺森德的人型生物身上找到布料。"}
D.ItemDescriptions[43911]={["9143a41f8399e4ee:22"]="有时候，维尔会觉得有些痒"}
D.ItemDescriptions[43929]={["1fc75b9587310428:19"]="吃一锤，疼两天"}
D.ItemDescriptions[43951]={["69f5e24752b91ada:50"]=S[13076]}
D.ItemDescriptions[43952]={["69f5e24752b91ada:50"]=S[13076]}
