D.ItemDescriptions[43968]={["cfd16b210d44e7ee:26"]="加入零件，然后使劲晃动。"}
D.ItemDescriptions[43986]={["69f5e24752b91ada:50"]=S[13076]}
D.ItemDescriptions[44012]={["8c4c74e7b70d5256:89"]="把这瓶药剂拿到眼前仔细观看之后，你发现它是由达拉然城中的各种废弃药水混合而成的。"}
D.ItemDescriptions[44066]={["dac60ee9578e3a02:17"]=S[9195]}
D.ItemDescriptions[44069]={["842f3879b46ea800:61"]=S[406]}
D.ItemDescriptions[44071]={["5c17bfda2f3f0295:23"]="保留鳞片，口感更松脆！"}
