D.ItemDescriptions[44153]={["fe83ca5255d24227:70"]="那个怪物的声音一直在你的脑海中回响，恳求你将钥匙交给它。"}
D.ItemDescriptions[44159]={["842f3879b46ea800:61"]=S[406]}
