D.ItemDescriptions[45947]={["540fd31b5f0fa97c:38"]="这把剑的表面上刻着无数的凹槽。"}
D.ItemDescriptions[45973]={["d3c7bc9d8f8bbbbc:18"]="绿色是新的流行色。"}
D.ItemDescriptions[45975]={["8cadef8281a794b9:11"]="计时腰带。"}
D.ItemDescriptions[45977]={["15c331d0cec701d9:132"]="这是一件精美无比的宝贝，表面上绘着一个正在游向一只天鹅的人。任何人都会愿意出大价钱买下它。把它弄丢了的人可真是个傻瓜。"}
