D.ItemDescriptions[45999]={["ae613ded2f6ebca4:64"]="这块玻璃上有星形的裂纹，似乎是砸中了什么东西之后留下的。"}
D.ItemDescriptions[46002]={["f9a597b91493e0d0:25"]="这东西带着一股酒味。"}
