D.ItemDescriptions[46348]={["97478b13b228c69e:184"]="教你学会永久性地为一件武器附魔，在攻击敌人或受到流血伤害时，它有可能触发储备血浆效果。当你的生命值过低时，储备血浆可以为你恢复生命值。附魔要求装备者的等级不得低于75级。"}
