D.ItemDescriptions[52712]={["7e810533673aa01a:39"]="把它放到野生肉鸡身上，然后就等着看戏吧！"}
D.ItemDescriptions[52714]={["d100bb8e24526119:43"]="因击穿加恩的肋骨而变形。"}
