D.ItemDescriptions[62339]={["de9458ccfbb28b1d:62"]="这本日记十分有爱的记录了杰克与艾泽拉斯野狼共度的时光。"}
D.ItemDescriptions[62348]={["faa6241cb50bc0bd:79"]="大地归于平静，喧嚣归于安宁，而你也更为专注，一击必中。——坚定者特尔拉斯"}
D.ItemDescriptions[62350]={["c68c8c921409da97:103"]="大地开始轰响，你的敌人在战栗。你出现了，毁灭也与你一同到来。——动荡者格尔西克"}
D.ItemDescriptions[62351]={["aa4e7822d13dbe4f:93"]="疾风的呼啸，大地的震颤，风暴的侵袭，这些也许会使你的身体倒下，但只要意志犹在，你就将屹立不倒。——亘久者翡尔森"}
D.ItemDescriptions[62352]={["e1ee0007764828b0:84"]="所有的灵魂在信任面前都会将潜在的天性显露无疑，即使是不该受到的信任。——耐心者岱亚曼塔"}
