D.ItemDescriptions[62510]={["b333a2e7eb2b8dce:42"]="至少黑铁矮人懂得品味好酒。"}
D.ItemDescriptions[62511]={["a9b255cc24b08ae3:22"]="适合熔铸。"}
D.ItemDescriptions[62513]={["077d1f1f42887e06:53"]="黑龙军团的未来也许就包藏在这蛋壳里。"}
D.ItemDescriptions[62533]={["71de875c51fd4977:62"]="这些武器原本是为强大的托维尔国王和将军们打造的。"}
D.ItemDescriptions[62540]={["b716a6c0cb3a1317:35"]="教你学会召唤超小版死亡之翼。"}
D.ItemDescriptions[62543]={["c77cd31d374e103a:25"]="有时放弃并不是件容易的事。"}
D.ItemDescriptions[62544]={["4e1099cf78793ec8:34"]="你可能得先把这东西弄掉……"}
D.ItemDescriptions[62545]={["1ed8c4b0282534fd:25"]="散发着家的熟悉气味。"}
D.ItemDescriptions[62546]={["da62e63df5db761c:36"]="已经传了几代人。"}
D.ItemDescriptions[62547]={["ae8ab5a55488514c:34"]="也许是被用于制作腰带。"}
D.ItemDescriptions[62550]={["ba0b7e34a8209b4d:55"]="这些花向着天空生长，即使是在最阴暗的角落里。"}
D.ItemDescriptions[62552]={["20a37192cbd95bc9:41"]="下一次尝试也许会为你带来更多好运。"}
D.ItemDescriptions[62553]={["211124de814e1695:24"]="离神秘的肉远一点儿。"}
D.ItemDescriptions[62554]={["55409de905b0ccc2:35"]="你真该好好对那只蜘蛛的尸体搜寻一番。"}
D.ItemDescriptions[62555]={["053694a13fdfc310:38"]="永远别相信诚实的地精和没喝醉酒的矮人。"}
D.ItemDescriptions[62556]={["f501fa5523a95e76:28"]="不搜寻尸体就永远不会知道你能找到什么。"}
D.ItemDescriptions[62557]={["ab275f58fd01ff97:35"]="你的未来因紫雨而变得迷蒙。"}
D.ItemDescriptions[62558]={["79223e73467c95a6:36"]="你将听到金币碰撞所发出的叮当之声。"}
D.ItemDescriptions[62559]={["0338f635cf15aa00:34"]="信仰光明，但要小心你的坐骑。"}
D.ItemDescriptions[62560]={["8138094e1e3013a7:31"]="永远不要站在巨龙的阴影之下。"}
D.ItemDescriptions[62561]={["8864b6b0d57677af:52"]="通往黑石山的道路看似花团锦簇。"}
D.ItemDescriptions[62562]={["c13f715850e08b03:38"]="你在不远的将来要遭遇多次灭团。"}
D.ItemDescriptions[62563]={["4ff65d9f285e1a96:49"]="史诗装备就像孩子一样——总是自己的好。"}
D.ItemDescriptions[62564]={["5b01ac00510facc5:60"]="你在今后的日子里将被经验值、荣誉点数和阵营声望所环绕。"}
D.ItemDescriptions[62565]={["75e4fade667b4815:57"]="你最宝贵的财富就在你朋友身上——尤其是坦克朋友。"}
D.ItemDescriptions[62566]={["fc2b75648cee1775:26"]="你的运道看来充满变数。"}
D.ItemDescriptions[62567]={["3999347a0f14e083:45"]="在平凡的物品中发现美丽。拿它们去换钱。"}
D.ItemDescriptions[62568]={["9cf88db001ada273:46"]="承诺去相亲的人，就像是一件“拾取后绑定”的物品。"}
D.ItemDescriptions[62569]={["d6ad7f4fc6356f56:30"]="萨满祭司的祝福充满元素性。"}
D.ItemDescriptions[62570]={["7c9ff224e3dfb8a5:49"]="你的前途一片光明，只要别撞见死亡之翼。"}
D.ItemDescriptions[62571]={["bf90e606cc01f3e5:43"]="你在不远的将来会有很大几率掷出100点。"}
D.ItemDescriptions[62572]={["94eea1c715e04a78:75"]="钓鱼这项专业技能可使你获得极大的放松（与耐心）。"}
D.ItemDescriptions[62573]={["f06069aedcbb220b:38"]="你总有一天会买得起那头坐骑。"}
D.ItemDescriptions[62574]={["a0367e83738a211e:109"]="补货时间到！若要邂逅更多好运，请与锈水港的F.B. 卡拉兹勒斯提克斯联系。批量购买还能打折哦！"}
D.ItemDescriptions[62575]={["7e1faca91088cbf0:55"]="你身上有许多尚未被发掘的天赋。只有勇于体验你才能获得更多。"}
D.ItemDescriptions[62576]={["c3f3818b00e2e1f8:50"]="能单挑一支军队的人是烈士；能单挑五个对手的人是壮士。"}
D.ItemDescriptions[62577]={["b4a1ba6cb95c5431:45"]="开朗的心情能伴你走过满布荆棘的战场。"}
D.ItemDescriptions[62578]={["20244994fdef7ba7:48"]="你所作出的所有努力足以抵得过修理费。"}
D.ItemDescriptions[62579]={["9722073e29d9b105:48"]="永远别相信巨魔。还有潜行者。尤其是巨魔潜行者。"}
D.ItemDescriptions[62580]={["a896cff96b83390a:26"]="怀疑会使法术尽毁。"}
D.ItemDescriptions[62581]={["d332906878d7f88f:52"]="现在是时候尝试点儿新东西了。也许可以学项新的商业技能。"}
D.ItemDescriptions[62582]={["8c53cd8ebc67f4ff:47"]="每种草药都有特定的盛放时间。然后就等你去摘了！"}
D.ItemDescriptions[62583]={["d95b8baea4811ad7:53"]="去休息一下吧。这是你应得的。不过记得要找间旅店！"}
D.ItemDescriptions[62584]={["d2adebe37caec78e:41"]="对灭团心存期待的人永远都不会有失望的那一天。"}
D.ItemDescriptions[62585]={["fba050083d6edbb3:44"]="当头上有飞行坐骑飞过时，千万不要向上看。"}
D.ItemDescriptions[62586]={["8971017af4e937d5:62"]="你将继承一大笔遗产。然后在拍卖行里挥霍一空。"}
D.ItemDescriptions[62587]={["eedfcf43beef6e78:34"]="附近有人想要对你/调情。"}
D.ItemDescriptions[62588]={["7f8e6d99f5c9d662:68"]="你的天赋一定会有出头的那一天。前提是你的天赋配点没有错。"}
D.ItemDescriptions[62589]={["8485def4f09948bb:48"]="救命！我被关在一间幸运饼干烘焙店里了！"}
D.ItemDescriptions[62590]={["369d8702a236c96b:24"]="明日的太阳将放射出万丈霞光。"}
D.ItemDescriptions[62591]={["38cc351f64e3c8ae:38"]="有个你恨的人会送你礼物。"}
D.ItemDescriptions[62592]={["c9064764ea966699:84"]="这块烧焦的木头散发着一种独特的气味。难怪狮鹫们能那么准确地作出反应。"}
D.ItemDescriptions[62593]={["914725db87e4f490:34"]="样本不断挪移晃动。"}
D.ItemDescriptions[62594]={["3430e62b511dd532:46"]="嵌在上面的宝石看起来被撬掉了。"}
D.ItemDescriptions[62595]={["16a4e98759e1b382:23"]="周身布满裂纹和缺口，老旧不堪。"}
D.ItemDescriptions[62596]={["0e4becac728e3f33:47"]=S[16890]}
D.ItemDescriptions[62597]={["236932da74edbfdf:10"]="就是块石头。"}
D.ItemDescriptions[62598]={["e834101d7f26cc4a:63"]="智慧源于探求的热望。毁于对理论的归结。"}
D.ItemDescriptions[62599]={["39290a4310f0c48a:59"]="你将过完长寿而幸福的一生，沿途屡历峰回路转。"}
D.ItemDescriptions[62600]={["4dca65c771917c3a:43"]="“脸滚键盘”绝非智慧之道。"}
D.ItemDescriptions[62601]={["dfc10388d38aa913:61"]="并非所有闪闪发光的东西都是金子。不过大多数情况下你都能拿它们去换金子。"}
D.ItemDescriptions[62602]={["a639afdd55b13680:56"]="你将与别人分享你的想法——你无力负担的想法。"}
