D.ItemDescriptions[66945]={["b199495bb345d988:64"]="尽管已远离浴血厮杀的战场，战痕斑斑的锤头仍在向人们讲述着激烈的战斗场面。"}
D.ItemDescriptions[66946]={["8fde6058b5ed6473:60"]="在这件古盔的顶部仍能看到致命伤所留下的痕迹。"}
D.ItemDescriptions[66947]={["ad3cabedfadc0a5e:60"]="锋利的脚爪，表面裹满了将这条巨龙焚烧至死的烈焰余烬。"}
