D.ItemDescriptions[74763]={["3d828ad3e17567d8:81"]="瓶子上刻着一行字：“皮囊易腐，灵魂不灭。”"}
D.ItemDescriptions[74768]={["3049cf79974bb0e6:61"]="这张卷轴上的陌生符号组成了一个令人着迷的图案。"}
D.ItemDescriptions[74812]={["f27de7e371d5f6c4:80"]="这种有毒的溶剂足以让你的朋友们对你敬而远之，并杀死你头发里的一切生物。"}
D.ItemDescriptions[74813]={["c78cd7162693bf55:66"]="山茱萸的萃取物，可用于给患有疥癣的动物洗澡。"}
D.ItemDescriptions[74815]={["949546dc25667837:55"]="特别调配，适用于敏感发炎的头皮。"}
D.ItemDescriptions[74822]={["999d592637381113:42"]="含有香草冰激凌的山泉水饮料，还在滋滋作响。"}
D.ItemDescriptions[74830]={["438b2d51ed4c521e:72"]="手握这块碎片会唤起你的每一段悲伤回忆。"}
D.ItemDescriptions[74918]={["3cbd38c56257d30c:19"]="先交钱，后提问。"}
D.ItemDescriptions[74925]={["c6e1e75cb1e5b731:50"]="这支蜡烛燃烧时火光明亮，但不会产生烟气。"}
D.ItemDescriptions[74955]={["62a4cefab6b63a87:13"]="从这头点燃。"}
D.ItemDescriptions[74958]={["b5bf74429015fc8f:31"]="在受伤时砸开。"}
D.ItemDescriptions[74981]={["9d6d0e19bc8fb050:35"]=S[13079]}
D.ItemDescriptions[75000]={["dedf4fd3145f3864:59"]="炽烈的火焰为你带来力量与安全感。"}
D.ItemDescriptions[75008]={["28b72f4f47600c0a:47"]="你知道怎么让它变好看吗？点上火！"}
D.ItemDescriptions[75013]={["eb8c89871124f736:39"]="教你学会烹制熊猫人大餐。"}
D.ItemDescriptions[75015]={["af284a8520480716:14"]="可用于烹饪。"}
D.ItemDescriptions[75017]={["3b07813abce59b91:44"]="教你学会烹制熊猫人盛宴。"}
D.ItemDescriptions[75023]={["dc7130f3c2968130:37"]="毫无光泽的丝线。"}
D.ItemDescriptions[75027]={["4da6573c2f4289b3:49"]="这当然是美味的鹿肉了！还能是什么？"}
D.ItemDescriptions[75028]={["0e96e85eccd0c09f:44"]="嘿嘿嘿嘿！咳咳……哼。嘿嘿！"}
D.ItemDescriptions[75029]={["5fa089937f65cb0e:42"]="面包烤……？我说的是“啤酒烤”，嘿嘿。"}
D.ItemDescriptions[75030]={["41b2a1643b689da3:59"]="裹上面包屑的小食，机械压制而成。我指的是，机械生产而成！"}
D.ItemDescriptions[75031]={["ea500f45e1883c92:38"]="蒸小面包。又称饺子，呵呵！"}
D.ItemDescriptions[75032]={["f6be34694e1d6268:29"]="选用美味的牛肉制成。呵呵！"}
D.ItemDescriptions[75033]={["aa9c3ce16d45b98e:54"]="选用凶猛的野生杜隆塔尔猪肉，嘿嘿，还有海鸥蛋哦，亲！"}
D.ItemDescriptions[75034]={["cc8327a17e34a006:49"]="怎么，原料当然来自提瑞斯法林地里肥美的鸭子和鹅了。"}
D.ItemDescriptions[75035]={["6139c70a3daa8e2f:41"]="亲爱的，这就是——巨魔风味的生肉。呵呵！"}
D.ItemDescriptions[75036]={["f72e770f79412f44:49"]="啊，永歌森林的肉牛特别筋道鲜嫩！"}
D.ItemDescriptions[75202]={["d500d83f74969bf8:30"]="全身滑溜溜的，而且布满斑点。"}
D.ItemDescriptions[75212]={["b4db473ef7ad697d:51"]="这个罐子的口足以塞进一条鱼，或者一只猢狲的手，但两者没法同时塞下去……"}
D.ItemDescriptions[75214]={["5d06b72a24b40cdf:57"]="这些菌菇吸饱了水汽，散发着淡淡的光辉。"}
D.ItemDescriptions[75217]={["a5a941d30dea3d30:67"]="这朵美丽的莲花散发着芬芳的气息。深呼吸，宁神静心……"}
D.ItemDescriptions[75219]={["03f6bc16aa6542e1:32"]="刚刚凋落的花瓣，有着完美的色彩。"}
D.ItemDescriptions[75220]={["b58cda4b504f6e78:27"]="漆黑、潮湿、散发着一股鱼腥味儿。"}
D.ItemDescriptions[75221]={["9cc05001a8821c48:51"]="一根锋利的尾针，很适合做成羽毛笔。"}
D.ItemDescriptions[75256]={["1c41fbb9b6477656:78"]="一大罐豆腐，很难运下山去。"}
D.ItemDescriptions[75258]={["c8334483a5712402:33"]="有点沉，很难搬运。"}
D.ItemDescriptions[75259]={["94f7bbc61eced37f:9"]="好大啊！"}
D.ItemDescriptions[75271]={["486369626a556f11:60"]="令人惊奇的是，他似乎很满足于被你装在包里带来带去。"}
D.ItemDescriptions[75272]={["1e1bd0ef021b9be4:69"]="她身上的白毛十分纤细，而且比一般的猪要长一点。"}
D.ItemDescriptions[75273]={["ebdb50908c05cc11:19"]="他很对得起他的名字。"}
D.ItemDescriptions[75274]={["cd216c32e1102fa7:55"]=S[5466]}
D.ItemDescriptions[75275]={["695ce0f1af9978b8:71"]="漆黑、荤腥、干瘦的肉排，来自穆山兽肩部，看上去不怎么吸引人。"}
D.ItemDescriptions[75276]={["3dac4da5e6caad7c:37"]="丰富的脂肪呈现出大理石纹路，味道有点冲。"}
D.ItemDescriptions[75525]={["30fcc6043df4f8e5:37"]="这种合剂饮之不尽。"}
D.ItemDescriptions[76062]={["9dbb8059792b7306:35"]="教会你如何召唤魔卒萨满。"}
D.ItemDescriptions[76091]={["1aa2a7fd92b4e68a:21"]="根本就不幸运。"}
D.ItemDescriptions[76100]={["829e15b494630f83:66"]="吓得簌簌发抖的小羊。出于某些原因，它就是不肯回家。"}
D.ItemDescriptions[76107]={["b5200a90618588ad:16"]="它瞪着你呢……"}
D.ItemDescriptions[76110]={["1e1fbf3b59527540:62"]="装满了今晨刚采摘的水果和蔬菜。"}
D.ItemDescriptions[76115]={["d63d6f2129624e88:44"]="这些五彩斑斓的翅膀上闪着神秘的彩光。"}
D.ItemDescriptions[76128]={["481bfdea1a13f84d:44"]="精心打磨的刀刃足以吹毛断发。"}
D.ItemDescriptions[76129]={["ad04eea97862ec76:18"]="出人意料地坚硬。"}
D.ItemDescriptions[76173]={["0bd38bb7e08e734a:32"]="戳两下，还会动呢。"}
D.ItemDescriptions[76174]={["e964a2862b5c3be1:52"]="雕刻精美，还散发着微弱的魔力波动。"}
D.ItemDescriptions[76209]={["3a1bc88ca307cd1f:50"]="一块随手切下的石头，看上去并不亚于精心雕琢的成品。"}
D.ItemDescriptions[76225]={["475f65a6bf2946b9:13"]="带着禽类特有的气味。"}
D.ItemDescriptions[76260]={["d9a3d47d0a2ff74a:32"]="一种已经经过软化处理的深水美味。"}
D.ItemDescriptions[76262]={["0f18784d809e2b54:50"]="在你实在不耐烦等鱼上钩时使用。"}
D.ItemDescriptions[76297]={["a768dd6fd55ed658:8"]="好大！"}
D.ItemDescriptions[76298]={["ee05d456e5c4f7f7:66"]="一只都没开过。或许兔妖根本不知道里面有什么？"}
D.ItemDescriptions[76305]={["c7107f8cbb1a77e9:81"]="从地狱咆哮之拳的残骸上偷来的信号弹，猢狲们似乎想把它当做近战武器来使用。"}
D.ItemDescriptions[76333]={["f10a9686769154a3:45"]="将它交给合适的人，就可以做出一些很好的木板。"}
D.ItemDescriptions[76334]={["f61488aac11ccf8b:30"]="一朵巨大、健康、芬芳的花。"}
D.ItemDescriptions[76335]={["b17879ed8faf9fea:9"]="深红色的液体。"}
D.ItemDescriptions[76336]={["28cc505e75c13529:18"]="穿肠烈酒。"}
D.ItemDescriptions[76337]={["89d366625e0bd96f:28"]="泥盏肯定很希望找回这袋啤酒花。"}
D.ItemDescriptions[76356]={["eb56c9b386598f3c:20"]="倒倒看！"}
D.ItemDescriptions[76362]={["10cc9a6e5e64c6c3:44"]="用来从河岸上收集泥水。"}
D.ItemDescriptions[76370]={["5ec37eb97cd1bb9c:25"]="看上去都有点像胡萝卜了。"}
D.ItemDescriptions[76401]={["bc1774b1bba64318:48"]="指尖传来的触感告诉你，这把钥匙即将支离破碎。"}
D.ItemDescriptions[76402]={["3b17116c54f9f22b:47"]="指尖传来的触感让你意识到这把钥匙正在朽化。"}
D.ItemDescriptions[76420]={["ec14c374664957c5:17"]="灰色的肉。"}
D.ItemDescriptions[76483]={["3b0a15c1cb06e298:58"]="一麻袋各种形状和大小的玉石饰品。"}
D.ItemDescriptions[76499]={["7af2449efd60bbd1:42"]="这种叶子表面覆盖着一层厚厚的蜡质。"}
D.ItemDescriptions[76501]={["7013686856ffeef9:26"]="和鸡蛋一样大。"}
D.ItemDescriptions[76502]={["dac60ee9578e3a02:17"]=S[9195]}
D.ItemDescriptions[76503]={["32432c39ad532a94:30"]="蛋很大，蛋壳却薄如蝉翼。"}
