D.ItemDescriptions[79030]={["d611765d24db1178:26"]="美味的金色蜂巢。"}
D.ItemDescriptions[79039]={["ca0ce3bf33cdd6ba:51"]="这块木头还不怎么干燥，勉强能生火。"}
D.ItemDescriptions[79043]={["bf1c39a2d9d1b477:42"]="这颗轻质小球充满了弹性。"}
D.ItemDescriptions[79046]={["1318e01aec2c47bd:73"]="这些像玻璃一样透明的小鱼有一股甜味，是野生蟒蛇的最爱。"}
D.ItemDescriptions[79049]={["69dbc437b000e84e:98"]="表面刻满古代文字的尘封遗物。翡翠林百木园的洁诺瓦·长目会对此感兴趣的。"}
D.ItemDescriptions[79058]={["01e676d4fe492511:67"]="这是一张饱经沧桑的脸，毫无生气的眼睛无辜地盯着你。"}
D.ItemDescriptions[79059]={["1383ccc524746402:55"]="这块逃过一劫的甲壳相对完整。"}
D.ItemDescriptions[79063]={["032cfc6199cb6098:39"]="比普通矿锄更加坚固、锋利。"}
D.ItemDescriptions[79067]={["15f380f8028c6bef:38"]="有点磨损了，但总体状况不错。"}
D.ItemDescriptions[79102]={["4017556e37573309:39"]=S[5483]}
D.ItemDescriptions[79120]={["2bc317ef40437dec:80"]="这件看似普通的遗物上满是尘土，破旧不堪，却涌动着奥术能量。"}
D.ItemDescriptions[79163]={["4aeef749ecbca80c:50"]="这种草药软膏中充满了神圣力量。"}
D.ItemDescriptions[79197]={["04847a93946d0000:52"]="如果你是一条鱼，看见这只虫子一定会流口水的。"}
D.ItemDescriptions[79198]={["2794bba7fc813b34:76"]="鲜亮的色彩和其中的鲜血都足以吸引饥饿的鱼儿。"}
D.ItemDescriptions[79199]={["fc7bf3a272ba69cf:24"]="眼睛还泛着微光。"}
D.ItemDescriptions[79201]={["f5f22f849c6680c5:64"]=S[20200]}
D.ItemDescriptions[79237]={["df2043a4a0f239b9:31"]="水里肯定有什么东西。"}
D.ItemDescriptions[79238]={["b1d602afc3b3d90c:11"]="好大一条啊……"}
D.ItemDescriptions[79244]={["10450c7d18df674c:5"]="十分稀有。"}
D.ItemDescriptions[79246]={["b9e0d3302cb7c063:110"]="传说锦绣花是永不凋谢的。这些花瓣显然并非如此，但它们确实散发着一股诱人的芳香。"}
D.ItemDescriptions[79249]={["4951a43e9b22d66b:45"]="书页上的文字都被恶魔力量烧毁了。"}
D.ItemDescriptions[79250]={["188e09e9a9c7e91e:30"]="味道有点像苹果。"}
D.ItemDescriptions[79251]={["ad55c2d999ea9f08:46"]="有很大的几率通过研磨潘达利亚的草药获得。"}
D.ItemDescriptions[79252]={["c8ac03d9bc0651fc:37"]="邪恶的刀锋上涂着一层黑色的油脂。"}
D.ItemDescriptions[79253]={["d279f79aa2c1869f:44"]="有较小的几率通过研磨潘达利亚的草药获得。"}
D.ItemDescriptions[79261]={["b33f2ab3be0a4e04:35"]="可打开部落密探的魔法镣铐。"}
D.ItemDescriptions[79264]={["4df976099cf821d2:97"]="闪闪发光的美丽宝石。四风谷的郝瀚·泥爪或迪娜·泥爪肯定会很喜欢这份礼物的。"}
D.ItemDescriptions[79265]={["0bc2a7e073d4ad89:99"]="如天空一般湛蓝的柔软羽毛。四风谷的老农山掌或吱吱可能会对它感兴趣。"}
D.ItemDescriptions[79266]={["2ad1320689cea05b:87"]="古老的遗物，饱经风霜。四风谷的玉儿·采苇或艾拉也许能看出它的价值。"}
D.ItemDescriptions[79267]={["83338d90afd0da85:71"]="多汁的红苹果。四风谷的阿烁或醉鬼贾古或许会喜欢。"}
D.ItemDescriptions[79268]={["8647a69cef273af5:99"]="能找到这种稀有的花朵意味着幸运。四风谷的农夫老方或吉娜·泥爪可能会喜欢。"}
D.ItemDescriptions[79269]={["bf20859123f972e8:73"]="能找到这种稀有的花朵意味着幸运。吉娜·泥爪可能会喜欢这件可爱的礼物。"}
D.ItemDescriptions[79318]={["5c17616fa286f584:59"]="一张随机的暗月迷雾卡片。集齐全套即可获得奖励。"}
D.ItemDescriptions[79320]={["506ed6fafb0f5bd1:18"]="半只多汁的苹果。"}
