D.ItemDescriptions[79833]={["23b8c0aaf01bf1ef:52"]="一离开土壤，它的光芒就迅速黯淡下来。"}
D.ItemDescriptions[79864]={["314c3ca6548d5377:50"]="能把你的皮肤都烧红的辣椒。记得先带上手套！"}
