D.ItemDescriptions[80061]={["4b5a093c41efd91d:102"]="虽然这份报告上一个字都没有，但你还是辨认出了一些滑水鱼的图画。你只需要脑补上空白的部分就行了。"}
D.ItemDescriptions[80071]={["cc44ee23f2dd34ee:51"]="周家世代相传的宝物。"}
D.ItemDescriptions[80074]={["fb953e36010eb86b:27"]="这块玉散发着纯净的能量。"}
D.ItemDescriptions[80116]={["b3d4e5dd22c29268:78"]="上面还留着锋利的齿印。但这些齿印太小了，似乎不是兔妖留下的。"}
D.ItemDescriptions[80122]={["1813ea35248f9318:39"]="这种多刺的根茎内富含酸涩的汁液。"}
D.ItemDescriptions[80133]={["8f8669595b35f59a:71"]="要么它们不喜欢腌菜的味道，要么它们根本不知道怎么打开罐子。"}
D.ItemDescriptions[80134]={["9d4a8c8f89f6ed3c:72"]="这块宝石吸收你掌心的温度后，逐渐变成了另一种颜色。"}
D.ItemDescriptions[80136]={["d37727b33fc31de6:24"]="一块结实的竹板。"}
D.ItemDescriptions[80137]={["b13b5c022c29b6c7:46"]="非常适合不怎么挑剔的熊猫人，大小正合适。"}
D.ItemDescriptions[80138]={["6f97399550991334:30"]="高价买来的头冠。"}
D.ItemDescriptions[80139]={["8fea982dbfe674b2:39"]="镶金嵌玉的银手镯。"}
D.ItemDescriptions[80140]={["1b9f84fbfbc16c7a:65"]="这种植物能够吸收土壤中的矿物，因此呈现出暗红色。"}
D.ItemDescriptions[80141]={["3eaee37a3e4a59f1:48"]="这朵美丽的白色百合在深邃、潮湿的山洞中盛放着。"}
D.ItemDescriptions[80142]={["c1c321ba726e4905:36"]="这种稀有的蘑菇散发着诡异的光芒。"}
D.ItemDescriptions[80143]={["f33786e7227e0de6:34"]="一种生长在高原地区的稀有苔藓。"}
D.ItemDescriptions[80144]={["b5e5bba7175dec1e:26"]="一大块肥厚多汁的肉排。"}
D.ItemDescriptions[80176]={["933e9979a03f84b2:55"]="稍微有点返潮，你只能指望那是海水而不是猢狲的口水了。"}
D.ItemDescriptions[80177]={["f470b7eb7ae3b3ca:29"]="锈迹斑斑，几乎无法使用。"}
D.ItemDescriptions[80184]={["965fd79deb36b456:44"]="这种多汁、甘甜的甜瓜只生长在汇风岭上。"}
D.ItemDescriptions[80213]={["e5fcdcf775a16bf4:17"]="叮当作响的硬币。"}
D.ItemDescriptions[80214]={["2c1653810674eda8:16"]="散发着牦牛毛的气味。"}
D.ItemDescriptions[80215]={["d5959f1024b4ed5b:29"]="装满了折叠整齐的钞票。"}
D.ItemDescriptions[80216]={["be73519d4adf0d14:32"]="胡乱塞了一些皱巴巴的钞票。"}
D.ItemDescriptions[80222]={["c06a476e454e80a1:58"]="这顶流光溢彩的古代战盔上没有一丝刮痕。"}
D.ItemDescriptions[80223]={["db9f71b5c0849a9e:45"]="根据你的近距离的观察……这的确是只好鸡！"}
D.ItemDescriptions[80227]={["35ae60a647607d5f:17"]="刚从农场采摘的新鲜蔬菜。"}
D.ItemDescriptions[80228]={["225c3bc3862b8a54:49"]="未经打磨的利齿——可以用来制作项链或手镯。"}
D.ItemDescriptions[80229]={["948674f2eb6c1bdd:9"]="蓝色的珍珠。"}
D.ItemDescriptions[80230]={["a9c71db433d1289b:27"]="上面积着一层陈年的牦牛油垢。"}
D.ItemDescriptions[80231]={["244bfbc0a517e41b:50"]="脆弱的花，小心打理。"}
D.ItemDescriptions[80232]={["a81f67b74b671486:66"]="虽然平原鹰有两条腿，但这条似乎更好吃一些。"}
D.ItemDescriptions[80233]={["a02a38562c6b24c7:17"]="烤得恰到好处！"}
D.ItemDescriptions[80234]={["13f10b776ce86eca:51"]="有点酥了，不过问题不大。"}
D.ItemDescriptions[80235]={["d4bf74ad8d9ecfc6:19"]="太酸了，难以下咽。"}
D.ItemDescriptions[80236]={["8e765c61bb8d584a:24"]="最好放在纸袋中饮用。"}
D.ItemDescriptions[80240]={["2af5c995d4a52dca:46"]="一只粗糙的圆球，用潘达利亚当地岩石雕成。"}
D.ItemDescriptions[80241]={["5d3688553b1d9524:59"]="这个朴素的手镯上雕刻着表达爱意的图案。"}
D.ItemDescriptions[80245]={["ea2452368cfd898b:81"]="好肉莫问出处。只要是肉就行了——或者，起码得有几分肉的模样。"}
D.ItemDescriptions[80260]={["c8e5db1d536988f6:34"]="最好不要长时间地拿着它。"}
D.ItemDescriptions[80262]={["52b761a1a6fa474a:47"]="戒指内壁上刻有字母缩写J.H.。"}
D.ItemDescriptions[80277]={["238f5fb923b1f956:17"]="滑溜溜的。"}
D.ItemDescriptions[80294]={["6065c30358c58dac:25"]="这玩意儿应该能值几个钱。"}
D.ItemDescriptions[80295]={["8fad63b22e0898d9:40"]="一个纸包，摇动时沙沙作响。"}
D.ItemDescriptions[80302]={["cd3773e2350f42d3:135"]="这些特别处理的种子能迅速发芽成熟，但生产出的卷心菜质量低下，主要用于培训新手农夫。"}
D.ItemDescriptions[80307]={["e08f02bf623fbcae:174"]="一堆挎包、袋子、盒子和各种包裹，与各种绳索线头缠绕在一起，比土地精本身还重。所有的物品上都散发着熏香和麝牛香的气味。"}
D.ItemDescriptions[80308]={["11a56924e440f8ff:80"]="这种气味浓郁的熏香能够让最胆小的人爆发出无穷的勇气。"}
D.ItemDescriptions[80310]={["c50bfd0947f2226c:44"]="这附近的鱼显然口味很古怪。"}
D.ItemDescriptions[80311]={["424597bfa6fc1f58:51"]="气味浓烈的漆黑物质在瓶中晃荡着。"}
D.ItemDescriptions[80312]={["1bf2d79368996968:45"]="这个空瓶子还散发着牦牛油和茉莉花的香味。"}
D.ItemDescriptions[80314]={["439ce7b11e229f6e:87"]="你的第一次收获！虽然不值什么钱，但对你来说意义非凡！"}
D.ItemDescriptions[80315]={["4824dc01f44c57d8:56"]="里面装满了产自各地的商品，几乎完好无损。"}
D.ItemDescriptions[80316]={["ac61138b3da43b3c:55"]="这个兔妖脚已经失去了往日的光彩，毛皮磨损严重并且污渍斑斑。"}
D.ItemDescriptions[80317]={["9938e33fddb0d2e6:42"]="这个生锈的牦牛蹄铁似乎能给人带来好运……"}
D.ItemDescriptions[80318]={["8e8e49634d2e37de:45"]="这株四叶草的叶子纯净得不可思议。"}
