D.ItemDescriptions[80433]={["ceed69bbef4030fa:58"]="只要一醒来，这只精魂就会想方设法钻进武器里去。"}
D.ItemDescriptions[80437]={["efcc40d4717f6a7b:30"]="这条鱼身上覆着一层沉重厚实的鳞片。"}
D.ItemDescriptions[80484]={["96c29e4faea60742:35"]="放在废墟高地的洞穴入口处。"}
D.ItemDescriptions[80511]={["2480a557ba8b7e40:37"]="这颗闪光的水晶发出微弱的嗡嗡声。"}
