D.ItemDescriptions[80808]={["1beb2d178b428d84:10"]="闪电。"}
D.ItemDescriptions[80810]={["c1d5c8db75d4bd34:70"]="一个人根本吃不下。睿智的阿娜·吴要这么多肉干什么？"}
