D.ItemDescriptions[81054]={["df94e8c19e2fe082:44"]="这种不起眼的小浆果有着强烈的效果。"}
D.ItemDescriptions[81055]={["4267f3cf5f1f9a66:40"]="可以乘坐暗月马戏团的旋转木马。"}
D.ItemDescriptions[81116]={["e7425623e6a81d30:38"]="这附近的鱼显然口味很古怪。"}
D.ItemDescriptions[81122]={["396cb29d011fae42:37"]="小心你的手指！"}
