D.ItemDescriptions[86404]={["ec2132d5bfbd1c3a:35"]="画在一张柔软皮革上的旧地图。"}
D.ItemDescriptions[86421]={["784b03ed0b2a4ebc:25"]="一本记载了毕生的学习与经验的书。"}
D.ItemDescriptions[86431]={["904cc6793b8a5ff8:75"]="书中的酿酒配方是用一种密文写成的，只有风暴烈酒家的人才能看懂。"}
D.ItemDescriptions[86433]={["9cf0a81d99aa893a:36"]="由上千颗闪闪发光的珠子串成。"}
D.ItemDescriptions[86434]={["cc7d7e28ee9395bb:24"]="相当雅致的头饰。"}
D.ItemDescriptions[86435]={["b3138984b9370ee5:10"]="闪闪发亮。"}
D.ItemDescriptions[86436]={["bff5f7a88082edad:27"]="刻有缩写字母T.M.。"}
D.ItemDescriptions[86446]={["344584ef5da71cd8:9"]="坏羊。"}
D.ItemDescriptions[86465]={["005e24f826feb425:31"]="一块发霉的羊皮，但很软。"}
D.ItemDescriptions[86467]={["afa0cc0e3875128f:67"]=S[14780]}
D.ItemDescriptions[86472]={["4d78347396ffa4fa:37"]="看来在琥珀中保存得十分完好。"}
D.ItemDescriptions[86473]={["9e1ff2f7b57b5e94:41"]="修建了断头阶梯的那把锤子。"}
D.ItemDescriptions[86476]={["1e16da1266a4fb03:91"]="永影巫王提安曾将这盏提灯的光作为其最强法术的能量之源。"}
D.ItemDescriptions[86477]={["199dc389143661d4:93"]="一段晦涩的古代文字表明，疯王蒙恩正是在失去这架天平之后才发了疯。"}
D.ItemDescriptions[86478]={["10872a0c61231033:128"]="无情战王齐昂是一位战略战术大师，引用他在这本论述中的一句话就是：“上兵伐骨，骨不可失。”"}
D.ItemDescriptions[86479]={["c1ba50b7e9621198:68"]="没有比匪王更贪婪的人，也没有比这更快的弓。"}
D.ItemDescriptions[86489]={["6afe944cf8731b57:48"]="一块来自壮硕动物的肉，出人意料地柔嫩。"}
D.ItemDescriptions[86511]={["afa0cc0e3875128f:67"]=S[14780]}
D.ItemDescriptions[86525]={["4f4f4a4aaa2e0905:68"]="觅血者斯基尔的甲壳碎片，上面浸透了他敌人的鲜血。"}
D.ItemDescriptions[86532]={["37ca341ddf22b140:16"]="杀死螳螂妖。"}
D.ItemDescriptions[86533]={["a973b9d21718b6af:54"]="微弱的光表明这不是普通的琥珀。"}
D.ItemDescriptions[86534]={["7bcd6b8801727ef9:40"]="是它发出的声音——而非其价值——吸引了螳螂妖。"}
D.ItemDescriptions[86536]={["5e64d897b7780bf2:36"]="悟道者使用的精致飞镖。"}
D.ItemDescriptions[86541]={["0d3372325b6c3a2d:103"]=S[18706]}
D.ItemDescriptions[86542]={["0fd3147940d7a5b0:29"]="长翅膀的鱼？这是一个新品种。"}
D.ItemDescriptions[86544]={["ca0c90144c839b73:53"]="小心那些刺，它们看上去很锋利。"}
D.ItemDescriptions[86545]={["56b99f875e6cebd2:81"]="就算是死了，这只奇怪的生物还是在不断变换色彩，与周围环境融为一体。"}
D.ItemDescriptions[86562]={["9d6d0e19bc8fb050:35"]=S[13079]}
D.ItemDescriptions[86563]={["503cf17121c0a4ee:35"]="教你学会召唤踏水黾。"}
D.ItemDescriptions[86564]={["2efdd6a86a0203fd:29"]="教你学会召唤小磨石。"}
D.ItemDescriptions[86565]={["2eeae466050b0afb:54"]="野牛人斥候随身携带的号角，用于向友军示警。"}
D.ItemDescriptions[86566]={["b801fa9f020bed7c:35"]="可防护锋利的碎石和荆棘。"}
D.ItemDescriptions[86567]={["29fa58991408a50e:52"]="野牛人巫医用来监测天气变化的工具。"}
D.ItemDescriptions[86569]={["eba4df85f1629730:32"]="它似乎在回瞪着你。"}
D.ItemDescriptions[86570]={["8364ab5d5ccd09b6:21"]="……他们还吃小狗！"}
D.ItemDescriptions[86571]={["8465d8ca34d394ab:68"]="魔古缚石者能使用这种刻着符文的水晶将血肉变成石头。"}
D.ItemDescriptions[86572]={["d53fbd12a50b41a5:28"]="灌注着强大的魔古魔法。"}
D.ItemDescriptions[86573]={["f985eb4330cb2ebc:50"]="一块来源不明的碎片，涌动着远古能量。"}
D.ItemDescriptions[86574]={["2cf9ab4284a7e357:40"]="可以听到瓶中传出的呢喃声。"}
D.ItemDescriptions[86575]={["575dfdf82524b17f:77"]="在魔古族的文化中，亵渎死去敌人的尸体是一项传统。"}
D.ItemDescriptions[86576]={["17c14c5e5f5b4edb:57"]="螳螂妖的剑术是不传之秘。"}
